esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// Counter, cumulative since the last pg_stat_reset(); INCREASE() gives how many deadlocks
// actually occurred inside the window and is reset-safe.
| STATS
    `Deadlocks` = SUM(INCREASE(pg_stat_database_deadlocks_total)),
    `Rollbacks` = SUM(INCREASE(pg_stat_database_xact_rollback_total))
  BY resource.attributes.supabase_project_ref
// Deadlocks are application bugs, so any occurrence is worth surfacing. Raise to a small
// positive number only if your workload has a known, tolerated baseline.
| WHERE `Deadlocks` > 0
| SORT `Deadlocks` DESC
